import ghidra.app.script.GhidraScript;import ghidra.app.decompiler.*;import ghidra.program.model.listing.*;import java.io.*;import java.util.*;
public class IpcTrace extends GhidraScript {public void run() throws Exception{PrintWriter p=new PrintWriter(new FileWriter(getScriptArgs()[0]));DecompInterface d=new DecompInterface();d.openProgram(currentProgram);Set<Function> todo=new LinkedHashSet<>();FunctionIterator fs=currentProgram.getFunctionManager().getFunctions(true);while(fs.hasNext()){Function f=fs.next();if(f.getName().startsWith("rq_msg_")||f.getName().startsWith("rq_prc_")||f.getName().startsWith("fc_msg_")||f.getName().startsWith("fs_msg_")||f.getName().startsWith("fc_ipc_")||f.getName().startsWith("fs_ipc_")||f.getName().startsWith("rq_ipc_"))todo.add(f);}for(int level=0;level<2;level++){Set<Function> more=new LinkedHashSet<>();for(Function f:todo)for(Function c:f.getCalledFunctions(monitor))if(!c.isExternal()&&!c.isThunk())more.add(c);todo.addAll(more);}for(Function f:todo){p.println("FUNCTION "+f.getName()+" @ "+f.getEntryPoint());DecompileResults r=d.decompileFunction(f,30,monitor);if(r.decompileCompleted())p.println(r.getDecompiledFunction().getC());InstructionIterator is=currentProgram.getListing().getInstructions(f.getBody(),true);while(is.hasNext()){Instruction i=is.next();p.println(i.getAddress()+" "+i);}}p.close();d.dispose();}}
